schemaSql:
-- Store settings / store status (open/closed for booking)
create table if not exists public.reserve_store_settings (
    id bigint generated always as identity primary key,
    is_booking_open boolean not null default true,
    closed_reason text,
    morning_slot_label text not null default 'صباح (6:00 ص - 11:00 ص)',
    evening_slot_label text not null default 'مساء (4:00 م - 9:00 م)',
    delivery_fee numeric(10, 2) not null default 0.00,
    updated_at timestamptz default now()
);

-- Catalog of dairy products
create table if not exists public.reserve_products (
    id bigint generated always as identity primary key,
    name text not null,
    description text,
    emoji text not null default '🥛',
    price numeric(10, 2) not null check (price >= 0),
    unit text not null check (unit in ('رطل', 'لتر', 'كيلو')),
    available_quantity numeric(10, 2) not null default 0.00 check (available_quantity >= 0),
    is_active boolean not null default true,
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

-- Extended customer details (address details: neighborhood, house number, etc.)
create table if not exists public.reserve_customer_details (
    customer_id uuid primary key references auth.users(id) on delete cascade,
    address text not null,
    registered_at timestamptz default now(),
    updated_at timestamptz default now()
);

-- Customer bookings / orders
create table if not exists public.reserve_orders (
    id bigint generated always as identity primary key,
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    product_id bigint not null references public.reserve_products(id) on delete restrict,
    quantity numeric(10, 2) not null check (quantity > 0),
    unit_price numeric(10, 2) not null check (unit_price >= 0),
    total_amount numeric(10, 2) not null check (total_amount >= 0),
    fulfillment_type text not null check (fulfillment_type in ('delivery', 'pickup')), -- توصيل أو استلام من المحل
    delivery_slot text not null check (delivery_slot in ('morning', 'evening')),     -- صباح أو مساء
    delivery_address text, -- Address at time of order if fulfillment_type = 'delivery'
    customer_name text not null,
    customer_phone text not null,
    notes text,
    status text not null default 'pending' check (status in ('pending', 'accepted', 'out_for_delivery', 'ready_for_pickup', 'delivered', 'rejected', 'cancelled')),
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

-- Enable RLS
alter table public.reserve_store_settings enable row level security;
alter table public.reserve_products enable row level security;
alter table public.reserve_customer_details enable row level security;
alter table public.reserve_orders enable row level security;

-- Policies for reserve_store_settings
drop policy if exists "Store settings read by authenticated" on public.reserve_store_settings;
create policy "Store settings read by authenticated"
    on public.reserve_store_settings
    for select
    to authenticated
    using (true);

drop policy if exists "Store settings manage by admin" on public.reserve_store_settings;
create policy "Store settings manage by admin"
    on public.reserve_store_settings
    for all
    to authenticated
    using (public.reserve_is_admin())
    with check (public.reserve_is_admin());

-- Policies for reserve_products
drop policy if exists "Products read by authenticated" on public.reserve_products;
create policy "Products read by authenticated"
    on public.reserve_products
    for select
    to authenticated
    using (true);

drop policy if exists "Products manage by admin" on public.reserve_products;
create policy "Products manage by admin"
    on public.reserve_products
    for all
    to authenticated
    using (public.reserve_is_admin())
    with check (public.reserve_is_admin());

-- Policies for reserve_customer_details
drop policy if exists "Customers manage own details" on public.reserve_customer_details;
create policy "Customers manage own details"
    on public.reserve_customer_details
    for all
    to authenticated
    using (customer_id = auth.uid() or public.reserve_is_admin())
    with check (customer_id = auth.uid() or public.reserve_is_admin());

-- Policies for reserve_orders
drop policy if exists "Customer can read own orders" on public.reserve_orders;
create policy "Customer can read own orders"
    on public.reserve_orders
    for select
    to authenticated
    using (customer_id = auth.uid() or public.reserve_is_admin());

drop policy if exists "Customer can insert own orders" on public.reserve_orders;
create policy "Customer can insert own orders"
    on public.reserve_orders
    for insert
    to authenticated
    with check (
        customer_id = auth.uid()
        and (
            exists (
                select 1 from public.reserve_store_settings
                where is_booking_open = true
            )
        )
    );

drop policy if exists "Customer can cancel own pending orders" on public.reserve_orders;
create policy "Customer can cancel own pending orders"
    on public.reserve_orders
    for update
    to authenticated
    using (customer_id = auth.uid() and status = 'pending')
    with check (customer_id = auth.uid() and status = 'cancelled');

drop policy if exists "Admin manage all orders" on public.reserve_orders;
create policy "Admin manage all orders"
    on public.reserve_orders
    for all
    to authenticated
    using (public.reserve_is_admin())
    with check (public.reserve_is_admin());

